-static void hclge_sync_fd_list(struct hclge_dev *hdev, struct hlist_head *hlist)
-{
-	struct hclge_fd_rule *rule;
-	struct hlist_node *node;
-	int ret = 0;
-
-	if (!test_and_clear_bit(HCLGE_STATE_FD_TBL_CHANGED, &hdev->state))
